    """Extend a 2x2 zero marker along its rows and columns, preserving 2s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    # The marker is the 2x2 zero block; extend the cross through its rows/columns.
    rows = {r for r, _ in zeros}
    cols = {c for _, c in zeros}
    for r in range(h):
        for c in range(w):
            if (r in rows or c in cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out

